import { Button } from "@/components/ui/button";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { ProductListThumbnail } from "@/components/ProductListThumbnail";
import { CatalogSourcePanel } from "@/components/CatalogSourcePanel";
import { trpc } from "@/lib/trpc";
import { skipToken } from "@tanstack/react-query";
import { AlertCircle, Check, CheckCircle2, ChevronDown, CircleAlert, CloudCog, ImagePlus, Images, Layers3, Pencil, RefreshCw, Save, Search, Sparkles, Trash2, X } from "lucide-react";
import { ChangeEvent, useEffect, useMemo, useState } from "react";

const missingFieldLabels: Record<string, string> = { "product.txt": "ملف البيانات", name: "اسم المنتج", description: "الوصف", sellingPrice: "السعر", sizes: "القياسات", images: "الصور" };
type WorkFilter = "needs_work" | "draft" | "ready" | "active" | "all";
type ProductSurface = "active" | "workspace";
type MediaItem = { mediaId: number; mediaType: "image" | "video" | "document"; playbackReady?: boolean; dataUrl: string; originalFileName: string; colorName: string | null; inventoryQuantity: number };
type ColorSuggestion = { colorNameArabic: string; confidence: number; mediaIds: number[]; reviewNote: string };

function fieldLabel(field: string) { return missingFieldLabels[field] ?? field; }
function safeSizes(raw: string | null) { try { const parsed = JSON.parse(raw ?? "[]"); return Array.isArray(parsed) ? parsed.filter((value): value is string => typeof value === "string") : []; } catch { return []; } }
function statusLabel(status: string) { return ({ draft: "مسودة", needs_review: "تحتاج مراجعة", ready: "جاهز للمراجعة", active: "نشط", archived: "مؤرشف" } as Record<string, string>)[status] ?? status; }
function statusClass(status: string) { return ({ draft: "bg-[#f1eee7] text-[#635d53]", needs_review: "bg-[#fff1de] text-[#a35d1c]", ready: "bg-[#e9f4ef] text-[#21624d]", active: "bg-[#e4f3ea] text-[#17633b]", archived: "bg-[#f0f0f0] text-[#747474]" } as Record<string, string>)[status] ?? "bg-slate-100 text-slate-700"; }
function catalogStageLabel(stage: string | null | undefined) { return ({ discovering_catalog: "جارٍ التحقق من مرجع Catalog", discovering_folders: "جارٍ اكتشاف مجلدات المنتجات", reading_product: "جارٍ قراءة ملفات المنتج", copying_operational_media: "جارٍ ضغط وتجهيز نسخ التشغيل", analyzing_colors: "جارٍ تحليل الألوان للمراجعة", processing_folders: "جارٍ تثبيت نتيجة المنتج", completed: "اكتمل آخر فحص", failed: "تعذر آخر فحص" } as Record<string, string>)[stage ?? ""] ?? "الفحص جاهز"; }
function formatElapsed(milliseconds: number) { const seconds = Math.max(0, Math.floor(milliseconds / 1000)); return seconds < 60 ? `${seconds} ثانية` : `${Math.floor(seconds / 60)} دقيقة${seconds % 60 ? ` و${seconds % 60} ثانية` : ""}`; }

function SectionTitle({ number, title, subtitle }: { number: string; title: string; subtitle: string }) { return <div className="flex gap-3"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#183d35] text-xs font-bold text-white">{number}</span><div><h3 className="font-bold text-[#183d35]">{title}</h3><p className="mt-0.5 text-xs leading-5 text-[#74817a]">{subtitle}</p></div></div>; }
function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) { return <label className="block text-sm font-medium text-[#4d6158]"><span>{label}</span>{hint && <span className="mr-1 text-xs font-normal text-[#8b968f]">{hint}</span>}<div className="mt-1.5">{children}</div></label>; }

function ColorCard({ colorName, quantity, media, onOpen }: { colorName: string; quantity: number; media: MediaItem[]; onOpen: () => void }) {
  const representative = media[0];
  return <button type="button" onClick={onOpen} className="group overflow-hidden rounded-3xl border border-[#e5ded2] bg-white text-right shadow-sm transition hover:-translate-y-0.5 hover:border-[#b9d3c6] hover:shadow-md"><div className="relative">{representative ? <img src={representative.dataUrl} alt={`صور لون ${colorName}`} className="aspect-[4/5] w-full object-cover" /> : <div className="grid aspect-[4/5] place-items-center bg-[#f5f2eb] text-[#98713f]"><ImagePlus className="h-7 w-7" /></div>}{media.length > 1 && <span className="absolute bottom-2 left-2 rounded-full bg-[#183d35]/90 px-2 py-1 text-xs font-bold text-white"><Images className="ml-1 inline h-3.5 w-3.5" />+{media.length - 1}</span>}</div><div className="p-4"><p className="text-base font-bold text-[#183d35]">{colorName}</p><p className="mt-2 text-2xl font-black text-[#a47d40]">{quantity} <span className="text-sm font-bold">قطعة</span></p><p className="mt-2 text-xs text-[#74817a]">اضغط لرؤية {media.length > 1 ? `كل الصور (${media.length})` : "الصورة"}</p></div></button>;
}

export default function Products() {
  const profile = trpc.access.myProfile.useQuery();
  const products = trpc.products.list.useQuery(undefined, { enabled: profile.isSuccess });
  const syncStatus = trpc.catalogSync.status.useQuery(undefined, { enabled: profile.isSuccess });
  const oneDriveStatus = trpc.integrations.oneDriveStatus.useQuery(undefined, { enabled: profile.isSuccess });
  const catalogSelectionStatus = trpc.integrations.catalogSelectionStatus.useQuery(undefined, { enabled: profile.isSuccess });
  const metaCatalogReadiness = trpc.metaCatalog.readiness.useQuery(undefined, { enabled: profile.isSuccess });
  const [selectedMetaCatalogAssetId, setSelectedMetaCatalogAssetId] = useState<number | null>(null);
  const metaCatalogPreviewInput = useMemo(() => selectedMetaCatalogAssetId ? { catalogAssetId: selectedMetaCatalogAssetId } : skipToken, [selectedMetaCatalogAssetId]);
  const metaCatalogPreview = trpc.metaCatalog.preview.useQuery(metaCatalogPreviewInput, { enabled: metaCatalogPreviewInput !== skipToken && profile.isSuccess });
  const deletedCatalogProducts = trpc.catalogSync.deletedProducts.useQuery(undefined, { enabled: profile.isSuccess });
  const [catalogRootPickerOpen, setCatalogRootPickerOpen] = useState(false);
  const catalogRootFolders = trpc.integrations.catalogRootFolders.useQuery(undefined, { enabled: profile.isSuccess && catalogRootPickerOpen && catalogSelectionStatus.data?.status === "connected" });
  const canEdit = profile.data?.permissions.includes("products.edit") ?? false;
  const canCreate = profile.data?.permissions.includes("products.create") ?? false;
  const canInventory = profile.data?.permissions.includes("products.inventory.update") ?? false;
  const canDelete = profile.data?.permissions.includes("products.delete") ?? false;
  const utils = trpc.useUtils();
  const [surface, setSurface] = useState<ProductSurface>("active");
  const [filter, setFilter] = useState<WorkFilter>("all");
  const [oneDrivePanelOpen, setOneDrivePanelOpen] = useState(false);
  const [metaCatalogPanelOpen, setMetaCatalogPanelOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [selectedProductId, setSelectedProductId] = useState<number | null>(null);
  const [openColor, setOpenColor] = useState<string | null>(null);
  const [editOpen, setEditOpen] = useState(false);
  const [productDeleteOpen, setProductDeleteOpen] = useState(false);
  const [colorDeleteTarget, setColorDeleteTarget] = useState<string | null>(null);
  const [restoreOpen, setRestoreOpen] = useState(false);
  const [restoreTarget, setRestoreTarget] = useState<{ productFolderId: string; productCode: string } | null>(null);
  const [selectedReviewMedia, setSelectedReviewMedia] = useState<number[]>([]);
  const [manualColorName, setManualColorName] = useState("");
  const [suggestions, setSuggestions] = useState<ColorSuggestion[]>([]);
  const [analysisNote, setAnalysisNote] = useState("");
  const [draftName, setDraftName] = useState("");
  const [draftDescription, setDraftDescription] = useState("");
  const [draftPrice, setDraftPrice] = useState("");
  const [draftPreviousPrice, setDraftPreviousPrice] = useState("");
  const [draftSizes, setDraftSizes] = useState("");
  const [quantityDrafts, setQuantityDrafts] = useState<Record<string, string>>({});
  const [renameDrafts, setRenameDrafts] = useState<Record<string, string>>({});
  const [newColorName, setNewColorName] = useState("");
  const [now, setNow] = useState(() => Date.now());
  const detailInput = useMemo(() => selectedProductId ? { productId: selectedProductId } : skipToken, [selectedProductId]);
  const selectedProduct = trpc.products.byId.useQuery(detailInput, { enabled: detailInput !== skipToken && profile.isSuccess });
  const selectedProductMedia = trpc.products.mediaPreviews.useQuery(detailInput, { enabled: detailInput !== skipToken && profile.isSuccess, staleTime: 5 * 60_000 });

  const invalidateProducts = async () => { await Promise.all([utils.products.list.invalidate(), utils.products.byId.invalidate(), utils.products.mediaPreviews.invalidate(), syncStatus.refetch()]); };
  const updateDetails = trpc.products.updateDetails.useMutation({ onSuccess: invalidateProducts });
  const uploadImage = trpc.products.uploadManualImage.useMutation({ onSuccess: invalidateProducts });
  const generateAutomaticSuggestion = trpc.products.generateAutomaticColorSuggestion.useMutation({ onSuccess: invalidateProducts });
  const reviewAutomaticSuggestion = trpc.products.reviewAutomaticColorSuggestion.useMutation({ onSuccess: invalidateProducts });
  const applyAutomaticSuggestion = trpc.products.applyAutomaticColorSuggestion.useMutation({ onSuccess: invalidateProducts });
  const analyzeColors = trpc.products.analyzeColors.useMutation();
  const addColor = trpc.products.addColor.useMutation({ onSuccess: invalidateProducts });
  const assignMediaColor = trpc.products.assignMediaColor.useMutation({ onSuccess: invalidateProducts });
  const saveColorInventory = trpc.products.saveColorInventory.useMutation({ onSuccess: invalidateProducts });
  const renameColor = trpc.products.renameColor.useMutation({ onSuccess: invalidateProducts });
  const deleteColor = trpc.products.deleteColor.useMutation({ onSuccess: invalidateProducts });
  const detachMedia = trpc.products.detachMedia.useMutation({ onSuccess: invalidateProducts });
  const deleteProduct = trpc.products.deletePermanently.useMutation({ onSuccess: invalidateProducts });
  const activateProduct = trpc.products.activate.useMutation({ onSuccess: invalidateProducts });
  const runCatalogScan = trpc.catalogSync.runNow.useMutation({
    onMutate: () => { window.setTimeout(() => { void syncStatus.refetch(); }, 250); },
    onSuccess: invalidateProducts,
  });
  const beginCatalogSelection = trpc.integrations.beginCatalogSelection.useMutation({
    onSuccess: result => { window.location.assign(result.authorizationUrl); },
  });
  const selectCatalogRoot = trpc.integrations.selectCatalogRoot.useMutation({
    onSuccess: async () => {
      await Promise.all([utils.integrations.catalogSelectionStatus.invalidate(), utils.integrations.catalogRootFolders.invalidate(), syncStatus.refetch()]);
      setCatalogRootPickerOpen(false);
    },
  });
  const restoreDeletedProduct = trpc.catalogSync.restoreDeletedProduct.useMutation({ onSuccess: async result => { await invalidateProducts(); await deletedCatalogProducts.refetch(); setRestoreTarget(null); setRestoreOpen(false); setSelectedProductId(result.productId); } });
  const exportMetaCatalog = trpc.metaCatalog.exportNow.useMutation({ onSuccess: () => { void utils.metaCatalog.jobs.invalidate(); } });
  const metaCatalogJobs = trpc.metaCatalog.jobs.useQuery(undefined, { enabled: profile.isSuccess });

  const detail = selectedProduct.data;
  const media = (selectedProductMedia.data ?? []) as MediaItem[];
  const colorNames = useMemo(() => Array.from(new Set(detail?.variants.map(variant => variant.colorName) ?? [])), [detail?.variants]);
  const imageMedia = useMemo(() => media.filter(item => item.mediaType === "image"), [media]);
  const videoMedia = useMemo(() => media.filter(item => item.mediaType === "video"), [media]);
  const mediaByColor = useMemo(() => colorNames.reduce((result, colorName) => ({ ...result, [colorName]: imageMedia.filter(item => item.colorName === colorName) }), {} as Record<string, MediaItem[]>), [colorNames, imageMedia]);
  const reviewMedia = imageMedia.filter(item => !item.colorName);
  const colorQuantities = useMemo(() => colorNames.reduce((result, colorName) => ({ ...result, [colorName]: detail?.variants.find(variant => variant.colorName === colorName)?.inventoryQuantity ?? 0 }), {} as Record<string, number>), [colorNames, detail?.variants]);
  const isCatalogRunning = syncStatus.data?.isRunning ?? false;
  const catalogElapsedMs = isCatalogRunning && syncStatus.data?.lastStartedAt ? now - new Date(syncStatus.data.lastStartedAt).getTime() : (syncStatus.data?.lastRunDurationMs ?? 0);
  const catalogProgress = syncStatus.data?.lastRunTotalFolders ? Math.min(100, Math.round(((syncStatus.data.lastRunProcessedFolders ?? 0) / syncStatus.data.lastRunTotalFolders) * 100)) : (isCatalogRunning ? 8 : 0);

  useEffect(() => {
    const readyAsset = metaCatalogReadiness.data?.assets.find(asset => asset.isSelected) ?? metaCatalogReadiness.data?.assets[0];
    if (readyAsset && !selectedMetaCatalogAssetId) setSelectedMetaCatalogAssetId(readyAsset.id);
  }, [metaCatalogReadiness.data, selectedMetaCatalogAssetId]);

  useEffect(() => {
    if (!isCatalogRunning) return;
    const intervalId = window.setInterval(() => {
      setNow(Date.now());
      void syncStatus.refetch();
    }, 2_000);
    return () => window.clearInterval(intervalId);
  }, [isCatalogRunning, syncStatus.refetch]);

  useEffect(() => {
    if (!detail) return;
    setDraftName(detail.product.name); setDraftDescription(detail.product.description ?? ""); setDraftPrice(detail.missingFields.includes("sellingPrice") ? "" : detail.product.sellingPrice); setDraftPreviousPrice(detail.product.previousPrice ?? ""); setDraftSizes(safeSizes(detail.product.sizeLabels).join("، "));
    setQuantityDrafts(colorNames.reduce((result, colorName) => ({ ...result, [colorName]: String(detail.variants.find(variant => variant.colorName === colorName)?.inventoryQuantity ?? 0) }), {}));
    setRenameDrafts(colorNames.reduce((result, colorName) => ({ ...result, [colorName]: colorName }), {}));
    setSuggestions(detail.pendingColorSuggestion?.suggestion.colorGroups ?? []); setAnalysisNote(detail.pendingColorSuggestion?.suggestion.overallReviewNote ?? ""); setSelectedReviewMedia([]); setManualColorName("");
  }, [detail?.product.id, detail?.pendingColorSuggestion?.operationId]);

  const workCounts = useMemo(() => ({ needs_work: products.data?.filter(product => product.status !== "active" && product.status !== "archived" && product.missingFields.length > 0).length ?? 0, draft: products.data?.filter(product => product.status === "draft").length ?? 0, ready: products.data?.filter(product => ["ready", "needs_review"].includes(product.status)).length ?? 0, active: products.data?.filter(product => product.status === "active").length ?? 0, workspace: products.data?.filter(product => !["active", "archived"].includes(product.status)).length ?? 0 }), [products.data]);
  const filteredProducts = useMemo(() => (products.data ?? []).filter(product => {
    const isInSurface = surface === "active" ? product.status === "active" : !["active", "archived"].includes(product.status);
    const matchesFilter = surface === "active" || filter === "all" || (filter === "needs_work" ? product.missingFields.length > 0 : filter === "draft" ? product.status === "draft" : filter === "ready" ? ["ready", "needs_review"].includes(product.status) : false);
    const keyword = search.trim().toLocaleLowerCase("ar");
    return isInSurface && matchesFilter && (!keyword || [product.name, product.productCode, product.category ?? "", ...product.missingFields.map(fieldLabel)].join(" ").toLocaleLowerCase("ar").includes(keyword));
  }), [products.data, surface, filter, search]);

  const saveDetails = () => { if (selectedProductId && draftName.trim()) updateDetails.mutate({ productId: selectedProductId, name: draftName.trim(), description: draftDescription.trim() || null, sellingPrice: draftPrice.trim() || undefined, sizeLabels: draftSizes.split(/[،,]/).map(size => size.trim()).filter(Boolean), previousPrice: draftPreviousPrice.trim() || null }); };
  const acceptAnalysis = (result: { colorGroups: ColorSuggestion[]; overallReviewNote: string }) => { setSuggestions(result.colorGroups); setAnalysisNote(result.overallReviewNote); };
  const analyzeSelected = async () => { if (!selectedProductId || !selectedReviewMedia.length) return; try { acceptAnalysis(await analyzeColors.mutateAsync({ productId: selectedProductId, mediaIds: selectedReviewMedia })); } catch { /* تعرض الواجهة رسالة الخطأ */ } };
  const approveColor = async (colorName: string, mediaIds: number[]) => { if (!selectedProductId || !colorName.trim() || !mediaIds.length) return; try { await addColor.mutateAsync({ productId: selectedProductId, colorName: colorName.trim() }); for (const mediaId of mediaIds) await assignMediaColor.mutateAsync({ productId: selectedProductId, mediaId, colorName: colorName.trim() }); setSuggestions(current => current.map(item => ({ ...item, mediaIds: item.mediaIds.filter(id => !mediaIds.includes(id)) })).filter(item => item.mediaIds.length > 0)); setSelectedReviewMedia(current => current.filter(id => !mediaIds.includes(id))); } catch { /* تعرض الواجهة رسالة الخطأ */ } };
  const toggleSuggestionMedia = (suggestionIndex: number, mediaId: number) => setSuggestions(current => current.map((suggestion, index) => index === suggestionIndex ? { ...suggestion, mediaIds: suggestion.mediaIds.includes(mediaId) ? suggestion.mediaIds.filter(id => id !== mediaId) : [...suggestion.mediaIds, mediaId] } : { ...suggestion, mediaIds: suggestion.mediaIds.filter(id => id !== mediaId) }));
  const acceptAutomaticReview = async () => { if (!detail?.pendingColorSuggestion || !suggestions.length) return; await applyAutomaticSuggestion.mutateAsync({ productId: detail.product.id, suggestionOperationId: detail.pendingColorSuggestion.operationId, groups: suggestions.map(suggestion => ({ colorName: suggestion.colorNameArabic, mediaIds: suggestion.mediaIds })) }); setSuggestions([]); };
  const rejectAutomaticReview = () => { if (detail?.pendingColorSuggestion) reviewAutomaticSuggestion.mutate({ productId: detail.product.id, suggestionOperationId: detail.pendingColorSuggestion.operationId, decision: "rejected" }); };
  const addImages = async (event: ChangeEvent<HTMLInputElement>) => { const files = Array.from(event.target.files ?? []); event.target.value = ""; if (!selectedProductId || !files.length) return; for (const file of files) { if (!/^image\/(jpeg|png|webp)$/.test(file.type)) continue; const base64Data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(typeof reader.result === "string" ? reader.result.split(",")[1] ?? "" : ""); reader.onerror = reject; reader.readAsDataURL(file); }); if (base64Data) await uploadImage.mutateAsync({ productId: selectedProductId, fileName: file.name, mimeType: file.type, base64Data }); } await generateAutomaticSuggestion.mutateAsync({ productId: selectedProductId }); };
  const saveQuantity = (colorName: string) => { if (!selectedProductId) return; const inventoryQuantity = Number(quantityDrafts[colorName]); if (!Number.isInteger(inventoryQuantity) || inventoryQuantity < 0) return; saveColorInventory.mutate({ productId: selectedProductId, colorName, inventoryQuantity }); };
  const saveColorDetails = async (colorName: string) => { if (!selectedProductId) return; const nextColorName = (renameDrafts[colorName] ?? colorName).trim(); const inventoryQuantity = Number(quantityDrafts[colorName]); if (!nextColorName || !Number.isInteger(inventoryQuantity) || inventoryQuantity < 0) return; if (nextColorName !== colorName) await renameColor.mutateAsync({ productId: selectedProductId, previousColorName: colorName, colorName: nextColorName }); await saveColorInventory.mutateAsync({ productId: selectedProductId, colorName: nextColorName, inventoryQuantity }); };
  const moveMedia = (mediaId: number, colorName: string) => { if (selectedProductId && colorName) assignMediaColor.mutate({ productId: selectedProductId, mediaId, colorName }); };
  const removeMedia = (mediaId: number) => { if (selectedProductId && window.confirm("سيُحذف مرجع الصورة من المنصة فقط. لن يتغير أصل OneDrive. هل تريد المتابعة؟")) detachMedia.mutate({ productId: selectedProductId, mediaId }); };
  const removeColor = (colorName: string) => setColorDeleteTarget(colorName);
  const confirmColorDelete = async () => { if (!selectedProductId || !colorDeleteTarget) return; await deleteColor.mutateAsync({ productId: selectedProductId, colorName: colorDeleteTarget, confirmColorName: colorDeleteTarget }); setColorDeleteTarget(null); };
  const createColor = async () => { if (!selectedProductId || !newColorName.trim()) return; await addColor.mutateAsync({ productId: selectedProductId, colorName: newColorName.trim() }); setNewColorName(""); };
  const removeProduct = async () => { if (!detail) return; await deleteProduct.mutateAsync({ productId: detail.product.id, confirmProductCode: detail.product.productCode }); setProductDeleteOpen(false); setEditOpen(false); setSelectedProductId(null); };
  const confirmRestoreProduct = async () => { if (!restoreTarget) return; await restoreDeletedProduct.mutateAsync({ productFolderId: restoreTarget.productFolderId }); };

  return <div dir="rtl" className="mx-auto w-full max-w-[1440px] space-y-5 pb-10">
    <header className="flex flex-col gap-4 border-b border-[#e6ded0] pb-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-sm font-medium text-[#98713f]">إدارة الكتالوج</p><h1 className="mt-1 text-3xl font-bold tracking-tight text-[#183d35]">المنتجات</h1><p className="mt-1 text-sm text-[#68756e]">يحلل النظام الصور تلقائيًا، ثم تؤكد ألوانها قبل ظهورها في صفحة المنتج.</p></div><div className="flex flex-wrap gap-2"><span className={`rounded-full border px-3 py-2 text-xs ${catalogSelectionStatus.data?.status === "catalog_selected" ? "border-[#cce0d7] bg-[#f1f8f4] text-[#506b61]" : catalogSelectionStatus.data?.status === "failed" ? "border-[#f0d6bc] bg-[#fff7ef] text-[#9c4b25]" : "border-[#eadcbf] bg-[#fffaf0] text-[#7a5a25]"}`}><CloudCog className="ml-1 inline h-3.5 w-3.5" />{catalogSelectionStatus.data?.status === "catalog_selected" ? `Catalog مرتبط: ${catalogSelectionStatus.data.selectedFolderName ?? "محدد"}` : catalogSelectionStatus.data?.status === "failed" ? "OneDrive يحتاج إصلاحًا" : "OneDrive اختياري وغير موصل"}</span><Button size="sm" variant="outline" onClick={() => setRestoreOpen(true)} disabled={!canCreate || deletedCatalogProducts.isLoading || !deletedCatalogProducts.data?.length} className="border-[#d5c29e] text-[#7a5a25]"><RefreshCw className="ml-1.5 h-3.5 w-3.5" />استعادة من Catalog{deletedCatalogProducts.data?.length ? ` (${deletedCatalogProducts.data.length})` : ""}</Button></div></header>
    <section className="grid gap-3 lg:grid-cols-[1.3fr_0.7fr]"><div className="rounded-3xl border border-[#d8e5de] bg-white p-3 shadow-[0_12px_28px_rgba(43,58,49,0.04)]"><div className="grid gap-2 sm:grid-cols-2"><button type="button" onClick={() => { setSurface("active"); setFilter("all"); setSelectedProductId(null); }} aria-pressed={surface === "active"} className={`rounded-2xl border p-4 text-right transition ${surface === "active" ? "border-[#183d35] bg-[#183d35] text-white shadow-md" : "border-transparent bg-[#f7fbf8] text-[#28463b] hover:border-[#cce0d7]"}`}><p className="text-xs font-bold opacity-80">عرض المتجر</p><div className="mt-2 flex items-end justify-between gap-3"><div><p className="text-lg font-black">المنتجات النشطة</p><p className="mt-1 text-xs leading-5 opacity-80">المنتجات المنشورة والجاهزة للعرض فقط.</p></div><span className={`rounded-full px-3 py-1 text-lg font-black ${surface === "active" ? "bg-white/15" : "bg-white text-[#183d35]"}`}>{workCounts.active}</span></div></button><button type="button" onClick={() => { setSurface("workspace"); setFilter("all"); setSelectedProductId(null); }} aria-pressed={surface === "workspace"} className={`rounded-2xl border p-4 text-right transition ${surface === "workspace" ? "border-[#8a6a35] bg-[#fff8eb] text-[#634822] shadow-sm" : "border-transparent bg-[#f8f6f0] text-[#4c554e] hover:border-[#e6d7b8]"}`}><p className="text-xs font-bold opacity-80">إدارة وتجهيز</p><div className="mt-2 flex items-end justify-between gap-3"><div><p className="text-lg font-black">مسودات العمل</p><p className="mt-1 text-xs leading-5 opacity-80">المسودات وما يحتاج إلى استكمال أو مراجعة.</p></div><span className={`rounded-full px-3 py-1 text-lg font-black ${surface === "workspace" ? "bg-[#f4e4bd]" : "bg-white text-[#72542a]"}`}>{workCounts.workspace}</span></div></button></div></div><div className="rounded-3xl border border-[#e6ded0] bg-[#fcfbf8] p-3 shadow-[0_12px_28px_rgba(43,58,49,0.04)]"><p className="px-2 pt-1 text-xs font-bold text-[#8a6a35]">أدوات عند الحاجة</p><div className="mt-2 grid gap-2"><button type="button" onClick={() => setOneDrivePanelOpen(value => !value)} aria-expanded={oneDrivePanelOpen} className="flex items-center justify-between rounded-2xl bg-white px-3 py-3 text-right text-sm font-bold text-[#28463b] transition hover:bg-[#f2f8f4]"><span className="flex items-center gap-2"><CloudCog className="h-4 w-4 text-[#28604e]" />مصدر المنتجات OneDrive</span><ChevronDown className={`h-4 w-4 transition-transform ${oneDrivePanelOpen ? "rotate-180" : ""}`} /></button><button type="button" onClick={() => setMetaCatalogPanelOpen(value => !value)} aria-expanded={metaCatalogPanelOpen} className="flex items-center justify-between rounded-2xl bg-white px-3 py-3 text-right text-sm font-bold text-[#28463b] transition hover:bg-[#fffaf0]"><span className="flex items-center gap-2"><Layers3 className="h-4 w-4 text-[#a47d40]" />تصدير Meta Catalog</span><ChevronDown className={`h-4 w-4 transition-transform ${metaCatalogPanelOpen ? "rotate-180" : ""}`} /></button></div></div></section>
    {oneDrivePanelOpen && <><CatalogSourcePanel canConfigure={canCreate} />{(isCatalogRunning || syncStatus.data?.lastRunStage === "failed") && <section className={`rounded-2xl border p-4 ${syncStatus.data?.lastRunStage === "failed" ? "border-[#f0d6bc] bg-[#fff7ef]" : "border-[#cce0d7] bg-[#f3faf5]"}`} aria-live="polite"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className={`text-sm font-bold ${syncStatus.data?.lastRunStage === "failed" ? "text-[#9c4b25]" : "text-[#245b4d]"}`}>{catalogStageLabel(syncStatus.data?.lastRunStage)}</p><p className="mt-1 text-xs text-[#64786e]">{isCatalogRunning ? (syncStatus.data?.lastRunCurrentProduct ? `المنتج الجاري: ${syncStatus.data.lastRunCurrentProduct}` : "قد يأخذ تجهيز الصور والفيديو وقتاً بحسب حجم الأصل.") : (syncStatus.data?.lastError ?? "راجع الخطأ أعلاه ثم أعد المحاولة عندما يصبح المرجع جاهزاً.")}</p></div><span className="rounded-full bg-white/80 px-3 py-1 text-xs font-bold text-[#536a60]">{isCatalogRunning ? `منذ ${formatElapsed(catalogElapsedMs)}` : "توقف الفحص"}</span></div>{isCatalogRunning && <><div className="mt-3 flex items-center justify-between text-xs text-[#64786e]"><span>{syncStatus.data?.lastRunTotalFolders ? `${syncStatus.data.lastRunProcessedFolders} من ${syncStatus.data.lastRunTotalFolders} مجلد` : "جارٍ حساب مجلدات العمل..."}</span><span>{catalogProgress}%</span></div><Progress value={catalogProgress} dir="rtl" className="mt-2 h-2.5 scale-x-[-1] bg-[#dcece1] [&_[data-slot=progress-indicator]]:bg-[#2c725a]" /></>}</section>}</>}
    {metaCatalogPanelOpen && <section className="rounded-3xl border border-[#d8e5de] bg-[#f7fbf8] p-4 shadow-[0_12px_28px_rgba(43,58,49,0.04)] sm:p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#8a6a35]">Meta Catalog</p><h2 className="mt-1 text-lg font-bold text-[#183d35]">تصدير المنتجات النشطة إلى كتالوج Meta</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-[#68756e]">المعاينة لا تنشر شيئاً. لا يُرسل إلا المنتج النشط الذي لديه متغير وصورة تشغيلية عامة، وتبقى التكلفة والهامش خارج الحمولة.</p></div><span className={`rounded-full px-3 py-1.5 text-xs font-bold ${metaCatalogReadiness.data?.capability?.enabled && metaCatalogReadiness.data.capability.status === "ready" ? "bg-[#e4f3ea] text-[#17633b]" : "bg-[#fff1de] text-[#a35d1c]"}`}>{metaCatalogReadiness.isLoading ? "جارٍ التحقق" : metaCatalogReadiness.data?.capability?.enabled && metaCatalogReadiness.data.capability.status === "ready" ? "جاهز للمعاينة" : "يحتاج إعداد Meta"}</span></div>{metaCatalogReadiness.isLoading ? <div className="mt-4 h-12 animate-pulse rounded-xl bg-white" /> : !metaCatalogReadiness.data?.assets.length ? <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#eadcbf] bg-[#fffaf0] p-3 text-xs text-[#7a5a25]"><span>لا يوجد أصل Catalog محدد أو أن قدرة catalog_management غير جاهزة.</span><Button size="sm" variant="outline" onClick={() => window.location.assign("/meta-connections")} className="border-[#d5c29e] text-[#7a5a25]">فتح مركز Meta</Button></div> : <div className="mt-4 space-y-3"><div className="flex flex-col gap-3 md:flex-row md:items-end"><label className="block flex-1 text-xs font-bold text-[#4d6158]"><span>أصل Catalog</span><select value={selectedMetaCatalogAssetId ?? ""} onChange={event => setSelectedMetaCatalogAssetId(Number(event.target.value) || null)} className="mt-1.5 h-10 w-full rounded-xl border border-[#d8e5de] bg-white px-3 text-sm font-normal text-[#30483e] outline-none focus:ring-2 focus:ring-[#9bc7b1]">{metaCatalogReadiness.data.assets.map(asset => <option key={asset.id} value={asset.id}>{asset.displayName ?? asset.externalId}{asset.isSelected ? " — محدد" : ""}</option>)}</select></label><Button size="sm" onClick={() => selectedMetaCatalogAssetId && exportMetaCatalog.mutate({ catalogAssetId: selectedMetaCatalogAssetId })} disabled={!canEdit || !selectedMetaCatalogAssetId || !metaCatalogPreview.data?.itemCount || exportMetaCatalog.isPending || !metaCatalogReadiness.data.capability?.enabled || metaCatalogReadiness.data.capability.status !== "ready"} className="bg-[#183d35] text-white hover:bg-[#245b4d]">{exportMetaCatalog.isPending ? "جارٍ إرسال الدفعات" : "تصدير إلى Meta"}</Button></div>{metaCatalogPreview.isLoading ? <p className="text-xs text-[#64786e]">جارٍ بناء معاينة آمنة…</p> : metaCatalogPreview.error ? <p className="text-xs text-[#9c4b25]">تعذر بناء المعاينة: {metaCatalogPreview.error.message}</p> : metaCatalogPreview.data ? <div className="flex flex-wrap items-center gap-2 text-xs text-[#536a60]"><span className="rounded-full bg-white px-3 py-1.5">{metaCatalogPreview.data.itemCount} عنصر قابل للتصدير</span><span className="rounded-full bg-white px-3 py-1.5">{metaCatalogPreview.data.skippedProducts} منتج يحتاج مراجعة</span><span className="rounded-full bg-white px-3 py-1.5">معاينة بلا بيانات مالية</span></div> : null}{metaCatalogJobs.data?.[0] && <div className="rounded-xl border border-[#e2ece5] bg-white px-3 py-2 text-xs text-[#536a60]">آخر تصدير: <strong>{metaCatalogJobs.data[0].status}</strong>{metaCatalogJobs.data[0].lastError ? <span className="mr-2 text-[#9c4b25]">{metaCatalogJobs.data[0].lastError}</span> : null}</div>}</div>}</section>}
    {(products.error || runCatalogScan.error || applyAutomaticSuggestion.error || metaCatalogPreview.error || exportMetaCatalog.error) && <div className="flex gap-3 rounded-2xl border border-[#f0d6bc] bg-[#fff7ef] p-4 text-sm text-[#9c4b25]"><AlertCircle className="h-5 w-5 shrink-0" />{products.error?.message ?? runCatalogScan.error?.message ?? applyAutomaticSuggestion.error?.message ?? metaCatalogPreview.error?.message ?? exportMetaCatalog.error?.message}</div>}
    <section className="rounded-3xl border border-[#e6ded0] bg-white p-3 shadow-[0_15px_38px_rgba(43,58,49,0.05)] sm:p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">{surface === "workspace" ? <div className="flex gap-1 overflow-x-auto rounded-2xl bg-[#f5f2eb] p-1.5">{([ ["needs_work", "يحتاج إكمالًا", workCounts.needs_work], ["draft", "مسودات", workCounts.draft], ["ready", "للمراجعة", workCounts.ready], ["all", "الكل", workCounts.workspace] ] as Array<[WorkFilter, string, number]>).map(([key, label, count]) => <button key={key} onClick={() => setFilter(key)} className={`whitespace-nowrap rounded-xl px-3 py-2 text-sm transition ${filter === key ? "bg-[#183d35] font-bold text-white" : "text-[#68756e] hover:bg-white"}`}>{label}<span className="mr-1.5 text-xs">{count}</span></button>)}</div> : <div className="rounded-2xl bg-[#edf8f1] px-4 py-2.5 text-sm font-bold text-[#245b4d]">يعرض هذا القسم المنتجات النشطة والمنشورة فقط <span className="mr-2 rounded-full bg-white px-2 py-1 text-xs">{workCounts.active} منتجات</span></div>}<div className="relative w-full lg:w-80"><Search className="absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#8a968f]" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث بالاسم أو الكود" className="h-11 rounded-xl border-[#ded8cd] pr-10" /></div></div></section>
    <section className={selectedProductId ? "grid gap-5 xl:grid-cols-[minmax(420px,0.9fr)_minmax(560px,1.3fr)]" : ""}><article className="overflow-hidden rounded-3xl border border-[#e6ded0] bg-white shadow-[0_15px_38px_rgba(43,58,49,0.05)]"><div className="flex items-center justify-between border-b border-[#eee9df] px-5 py-4"><div><h2 className="font-bold text-[#183d35]">قائمة العمل</h2><p className="mt-0.5 text-xs text-[#7b857f]">{filteredProducts.length} نتيجة</p></div><Layers3 className="h-5 w-5 text-[#a78550]" /></div>{products.isLoading ? <div className="space-y-3 p-5"><div className="h-20 animate-pulse rounded-2xl bg-[#f5f2eb]" /><div className="h-20 animate-pulse rounded-2xl bg-[#f5f2eb]" /></div> : <div className="divide-y divide-[#eee9df]">{filteredProducts.map(product => <button key={product.id} onClick={() => setSelectedProductId(product.id)} className={`w-full px-4 py-4 text-right transition ${selectedProductId === product.id ? "bg-[#eef7f2]" : "hover:bg-[#fcfbf8]"}`}><div className="flex gap-3"><ProductListThumbnail imageUrl={product.primaryImageUrl} alt={product.primaryImageAlt ?? `صورة ${product.name}`} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><div><p className="truncate font-bold text-[#263f36]">{product.name}</p><p className="mt-0.5 text-xs text-[#7a837d]">{product.productCode}</p></div><span className={`rounded-full px-2.5 py-1 text-xs ${statusClass(product.status)}`}>{statusLabel(product.status)}</span></div><div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-[#4e675d]"><span>{product.missingFields.includes("sellingPrice") ? "أضف السعر" : `${product.sellingPrice} د.ع`}</span>{product.previousPrice && Number(product.previousPrice) > Number(product.sellingPrice) && <del className="text-[#9a8e80]">{product.previousPrice} د.ع</del>}</div></div></div></button>)}</div>}</article>
      {selectedProductId && <article className="min-h-[680px] overflow-hidden rounded-3xl border border-[#e6ded0] bg-white shadow-[0_15px_38px_rgba(43,58,49,0.05)]">{selectedProduct.isLoading && <div className="p-6 text-sm text-[#526a60]">جارٍ فتح المنتج...</div>}{detail && <div><header className="flex items-start justify-between border-b border-[#e9e4da] px-5 py-5 sm:px-6"><div className="flex gap-3">{media[0] ? <img src={media[0].dataUrl} alt={`صورة ${detail.product.name}`} className="h-16 w-16 rounded-2xl object-cover" /> : <div className="grid h-16 w-16 place-items-center rounded-2xl bg-[#f2eee6]"><ImagePlus className="h-5 w-5" /></div>}<div><h2 className="text-xl font-bold text-[#183d35]">{detail.product.name}</h2><p className="mt-1 text-xs text-[#74817a]">{detail.product.productCode}</p><p className="mt-2 text-xs font-medium text-[#a06122]">{detail.missingFields.length ? `${detail.missingFields.length} عناصر تحتاج إكمالًا` : "البيانات الأساسية مكتملة"}</p></div></div><div className="flex gap-2"><Button variant="outline" onClick={() => setEditOpen(true)} disabled={!canEdit} className="border-[#b8d4c7] text-[#28604e]"><Pencil className="ml-1.5 h-4 w-4" />تعديل المنتج</Button><Button size="icon" variant="ghost" onClick={() => setSelectedProductId(null)} aria-label="إغلاق التفاصيل"><X className="h-4 w-4" /></Button></div></header>{detail.missingFields.length > 0 && <div className="mx-5 mt-5 flex flex-wrap gap-2 rounded-2xl border border-[#f1d8bd] bg-[#fff9f1] p-3 text-xs text-[#8f5527]">{detail.missingFields.map(field => <span key={field}><CircleAlert className="ml-1 inline h-3.5 w-3.5" />ينقص {fieldLabel(field)}</span>)}</div>}<div className="space-y-8 px-5 py-6 sm:px-6"><section><SectionTitle number="1" title="بيانات المنتج" subtitle="بيانات مختصرة؛ استخدم «تعديل المنتج» لتغييرها." /><div className="mt-4 grid grid-cols-2 gap-3 rounded-2xl bg-[#f8f6f0] p-4 text-sm"><p><span className="text-[#74817a]">السعر: </span><b>{detail.product.sellingPrice} د.ع</b>{detail.product.previousPrice && Number(detail.product.previousPrice) > Number(detail.product.sellingPrice) && <del className="mr-2 text-xs text-[#9a8e80]">{detail.product.previousPrice} د.ع</del>}</p><p><span className="text-[#74817a]">القياسات: </span><b>{safeSizes(detail.product.sizeLabels).join("، ") || "لا توجد"}</b></p><p className="col-span-2 text-[#586a61]">{detail.product.description || "لا يوجد وصف بعد."}</p></div></section><section><SectionTitle number="2" title="الألوان والكميات" subtitle="تظهر صورة ممثلة واحدة لكل لون. اضغط البطاقة لرؤية الصور الأخرى." />{colorNames.length ? <div className="mt-4 grid grid-cols-2 gap-4 sm:grid-cols-3">{colorNames.map(colorName => <ColorCard key={colorName} colorName={colorName} quantity={colorQuantities[colorName] ?? 0} media={mediaByColor[colorName] ?? []} onOpen={() => setOpenColor(colorName)} />)}</div> : <div className="mt-4 rounded-2xl border border-dashed border-[#d9d0c1] bg-[#fcfaf6] p-5 text-sm text-[#7a786f]">لا توجد ألوان معتمدة بعد. تظهر المراجعة أدناه بعد تحليل الصور.</div>}</section>{detail.pendingColorSuggestion || suggestions.length ? <section className="rounded-3xl border border-[#ead8b7] bg-[#fffaf0] p-4"><SectionTitle number="3" title="مراجعة الاقتراحات" subtitle={detail.pendingColorSuggestion ? "عدّل الاسم والصور داخل كل اقتراح ثم اعتمدها دفعة واحدة." : "حللت الصور المحددة. اعتمد كل مجموعة أو عدلها ثم انتقل إلى المجموعة التالية."} /><div className="mt-4 grid gap-3 sm:grid-cols-2">{suggestions.map((suggestion, index) => <div key={`suggestion-${index}`} className="rounded-2xl border border-[#eddfc4] bg-white p-3"><div className="flex gap-2"><Input value={suggestion.colorNameArabic} onChange={event => setSuggestions(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, colorNameArabic: event.target.value } : item))} aria-label="اسم اللون المقترح" /><Button size="icon" variant="outline" onClick={() => setSuggestions(current => current.filter((_, itemIndex) => itemIndex !== index))} aria-label="حذف الاقتراح" className="border-[#efd5cf] text-[#a14724]"><Trash2 className="h-4 w-4" /></Button></div><p className="mt-2 text-xs text-[#786a57]">اختر صور هذا اللون؛ اختيار الصورة هنا ينقلها من أي اقتراح آخر.</p><div className="mt-3 grid grid-cols-4 gap-2">{media.map(item => { const selected = suggestion.mediaIds.includes(item.mediaId); return <button type="button" key={item.mediaId} onClick={() => toggleSuggestionMedia(index, item.mediaId)} aria-pressed={selected} className={`relative overflow-hidden rounded-xl border-2 ${selected ? "border-[#a47d40] ring-2 ring-[#ead7ac]" : "border-transparent opacity-45 hover:opacity-100"}`}><img src={item.dataUrl} alt="صورة للاقتراح" className="aspect-square w-full object-cover" />{selected && <span className="absolute inset-0 grid place-items-center bg-[#183d35]/30 text-white"><Check className="h-4 w-4" /></span>}</button>; })}</div><p className="mt-2 text-xs font-medium text-[#786a57]">{suggestion.mediaIds.length} صور مختارة · ثقة {Math.round(suggestion.confidence * 100)}%</p>{!detail.pendingColorSuggestion && <Button onClick={() => approveColor(suggestion.colorNameArabic, suggestion.mediaIds)} disabled={!suggestion.colorNameArabic.trim() || !suggestion.mediaIds.length || addColor.isPending || assignMediaColor.isPending} className="mt-3 w-full bg-[#285f4e] hover:bg-[#1c4b3d]"><Check className="ml-1 h-4 w-4" />اعتماد هذه المجموعة</Button>}</div>)}</div><p className="mt-3 text-xs text-[#8b7659]">{analysisNote || "راجع الصور المقترحة قبل تأكيدها."}</p>{detail.pendingColorSuggestion && <div className="mt-4 flex flex-wrap gap-2"><Button onClick={acceptAutomaticReview} disabled={!suggestions.length || suggestions.some(item => !item.colorNameArabic.trim() || !item.mediaIds.length) || applyAutomaticSuggestion.isPending} className="bg-[#285f4e] hover:bg-[#1c4b3d]"><Check className="ml-1 h-4 w-4" />اعتماد الاقتراحات المعدلة</Button><Button variant="outline" onClick={rejectAutomaticReview} disabled={reviewAutomaticSuggestion.isPending} className="border-[#d6c9b6] text-[#765f3c]">رفض الاقتراح كاملًا</Button></div>}</section> : null}{reviewMedia.length > 0 && <section className="rounded-3xl border border-[#e9d6ad] bg-[#fffaf1] p-4"><SectionTitle number="4" title="صور غير مسندة إلى لون" subtitle={`هذه الصور بقيت خارج الألوان المعتمدة (${reviewMedia.length} صورة). لن تختفي حتى تسندها أو تحذفها أنت.`} /><div className="mt-3 flex flex-wrap gap-2">{reviewMedia.map(item => <button type="button" key={item.mediaId} onClick={() => setSelectedReviewMedia(current => current.includes(item.mediaId) ? current.filter(id => id !== item.mediaId) : [...current, item.mediaId])} className={`relative h-20 w-20 overflow-hidden rounded-xl border-2 ${selectedReviewMedia.includes(item.mediaId) ? "border-[#a47d40] ring-2 ring-[#ead7ac]" : "border-[#eadfce]"}`}><img src={item.dataUrl} alt="صورة غير مسندة" className="h-full w-full object-cover" />{selectedReviewMedia.includes(item.mediaId) && <span className="absolute inset-0 grid place-items-center bg-[#183d35]/35 text-white"><Check className="h-5 w-5" /></span>}</button>)}</div><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_auto_auto]"><Input value={manualColorName} onChange={event => setManualColorName(event.target.value)} placeholder="اكتب اسم اللون للصور المحددة" /><Button variant="outline" onClick={analyzeSelected} disabled={!selectedReviewMedia.length || analyzeColors.isPending} className="border-[#b8d4c7] text-[#28604e]"><Sparkles className="ml-1 h-4 w-4" />حلل المحدد</Button><Button onClick={() => approveColor(manualColorName, selectedReviewMedia)} disabled={!manualColorName.trim() || !selectedReviewMedia.length || addColor.isPending} className="bg-[#285f4e] hover:bg-[#1c4b3d]"><Check className="ml-1 h-4 w-4" />تسمية وربط</Button></div></section>}<section className="border-t border-[#eee9df] pt-6"><details><summary className="flex cursor-pointer list-none items-center justify-between font-bold text-[#4a6459]">مصدر Catalog وسجل العمل <ChevronDown className="h-4 w-4" /></summary><p className="mt-3 text-sm leading-6 text-[#718078]">Catalog يُقرأ في الخلفية فقط. لا تُعدّل المنصة ملفات OneDrive، ولا يغير تأكيد اللون حالة النشر.</p></details></section></div></div>}</article>}</section>
    {selectedProductId && detail && <section className={`rounded-3xl border p-5 shadow-[0_15px_38px_rgba(43,58,49,0.05)] ${detail.reviewReadiness.ready ? "border-[#bddbc9] bg-[#f2fbf5]" : "border-[#f1d8bd] bg-[#fffaf2]"}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className={`text-lg font-bold ${detail.reviewReadiness.ready ? "text-[#21624d]" : "text-[#8f5527]"}`}>{detail.reviewReadiness.ready ? "جاهز للمراجعة" : "تحتاج مراجعة"}</p><p className="mt-1 text-sm text-[#60736a]">{detail.publishEligibility.message}</p></div><span className={`rounded-full px-3 py-1.5 text-xs font-bold ${detail.publishEligibility.eligible ? "bg-[#dff3e5] text-[#21624d]" : "bg-[#f5ead7] text-[#8f5527]"}`}>{detail.publishEligibility.eligible ? "قابل للنشر بعد اعتماد آلية التفعيل" : "غير قابل للنشر بعد"}</span></div>{!detail.reviewReadiness.ready && <ul className="mt-3 space-y-1 text-xs text-[#8f5527]">{detail.reviewReadiness.reasons.map(reason => <li key={reason}><CircleAlert className="ml-1 inline h-3.5 w-3.5" />{reason}</li>)}</ul>}<p className="mt-3 text-xs text-[#60736a]">هذه حالة تشغيلية فقط؛ لا يوجد زر نشر أو انتقال إلى «نشط» قبل اعتماد آلية التفعيل المنفصلة.</p></section>}
    {selectedProductId && detail && detail.product.status !== "active" && detail.publishEligibility.eligible && <section className="rounded-3xl border border-[#b9d7c5] bg-[#f2fbf5] p-5 shadow-[0_15px_38px_rgba(43,58,49,0.05)]"><p className="font-bold text-[#21624d]">المنتج جاهز للاعتماد</p><p className="mt-1 text-sm text-[#60736a]">اضغط اعتماد المنتج لتحويله إلى «نشط» في الكتالوج. سيُسجل اسم المعتمد ووقت الاعتماد.</p><Button onClick={() => activateProduct.mutate({ productId: detail.product.id })} disabled={!canEdit || activateProduct.isPending} className="mt-3 bg-[#21624d] hover:bg-[#174a39]"><Check className="ml-1 h-4 w-4" />{activateProduct.isPending ? "جارٍ اعتماد المنتج..." : "اعتماد المنتج"}</Button>{activateProduct.error && <p className="mt-2 text-xs text-[#9c3f2d]">{activateProduct.error.message}</p>}</section>}
    {selectedProductId && videoMedia.length > 0 && <section className="rounded-3xl border border-[#d7dbe8] bg-white p-5 shadow-[0_15px_38px_rgba(43,58,49,0.05)]"><SectionTitle number="ف" title="فيديوهات المنتج" subtitle="فيديوهات مستقلة من Catalog؛ لا تدخل في تحليل الألوان." /><div className="mt-4 grid gap-4 sm:grid-cols-2">{videoMedia.map(video => <div key={video.mediaId} className="mx-auto w-full max-w-[280px] overflow-hidden rounded-2xl border border-[#e6ded0] bg-[#101b18]">{video.playbackReady && video.dataUrl ? <video controls preload="metadata" className="aspect-[9/16] w-full object-contain" src={video.dataUrl}>لا يدعم المتصفح تشغيل الفيديو.</video> : <div className="grid aspect-[9/16] place-items-center gap-3 p-4 text-center text-sm text-white"><span>الفيديو محفوظ في Catalog، وتعذر تجهيز نسخة تشغيلية له حاليًا. لن يؤثر ذلك في صور المنتج أو تحليل ألوانه.</span>{video.dataUrl && <a href={video.dataUrl} target="_blank" rel="noreferrer" className="rounded-lg bg-white px-3 py-2 text-xs font-bold text-[#285f4e]">فتح الفيديو الأصلي في OneDrive</a>}</div>}<p className="truncate bg-white px-3 py-2 text-xs text-[#526a60]">{video.originalFileName}</p></div>)}</div></section>}
    <Dialog open={restoreOpen} onOpenChange={setRestoreOpen}><DialogContent dir="rtl" className="max-h-[80vh] max-w-xl overflow-y-auto"><DialogHeader><DialogTitle>استعادة منتج من Catalog</DialogTitle><DialogDescription>تعرض هذه القائمة المنتجات التي حذفت من المنصة وما زالت موجودة في OneDrive. اختر منتجًا لاستعادته كمسودة فقط.</DialogDescription></DialogHeader>{deletedCatalogProducts.isLoading ? <p className="py-6 text-center text-sm text-[#718078]">جارٍ قراءة قائمة المنتجات القابلة للاستعادة...</p> : !deletedCatalogProducts.data?.length ? <p className="rounded-2xl bg-[#f8f6f0] p-5 text-sm text-[#718078]">لا توجد منتجات محذوفة متاحة للاستعادة الآن.</p> : <div className="space-y-3">{deletedCatalogProducts.data.map(item => <div key={item.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[#e6ded0] p-4"><div><p className="font-bold text-[#183d35]">{item.productCode}</p><p className="mt-1 text-xs text-[#718078]">{item.groupName} · {item.imageCount} صور</p></div><Button onClick={() => setRestoreTarget({ productFolderId: item.productFolderId, productCode: item.productCode })} className="bg-[#285f4e] hover:bg-[#1c4b3d]"><RefreshCw className="ml-1 h-4 w-4" />استعادة كمسودة</Button></div>)}</div>}{restoreDeletedProduct.error && <p className="rounded-xl bg-[#fff0ec] p-3 text-xs text-[#9c3f2d]">{restoreDeletedProduct.error.message}</p>}</DialogContent></Dialog>
    <AlertDialog open={Boolean(restoreTarget)} onOpenChange={open => !open && setRestoreTarget(null)}><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>هل تريد استعادة المنتج {restoreTarget?.productCode}؟</AlertDialogTitle><AlertDialogDescription>سيقرأ النظام مجلد المنتج من Catalog وينشئه من جديد كمسودة. لن يغير أي ملف في OneDrive، ولن ينشر المنتج.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>لا</AlertDialogCancel><AlertDialogAction onClick={confirmRestoreProduct} className="bg-[#285f4e] hover:bg-[#1c4b3d]">نعم، استعده كمسودة</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <Dialog open={Boolean(openColor)} onOpenChange={open => !open && setOpenColor(null)}><DialogContent dir="rtl" className="max-h-[85vh] max-w-3xl overflow-y-auto"><DialogHeader><DialogTitle>صور لون {openColor}</DialogTitle><DialogDescription>هذه الصور مرتبطة باللون نفسه داخل المنتج.</DialogDescription></DialogHeader><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{openColor && (mediaByColor[openColor] ?? []).map(item => <img key={item.mediaId} src={item.dataUrl} alt={`صورة لون ${openColor}`} className="aspect-[4/5] rounded-2xl object-cover" />)}</div></DialogContent></Dialog>
    <Dialog open={editOpen} onOpenChange={setEditOpen}><DialogContent dir="rtl" className="max-h-[90vh] max-w-4xl overflow-y-auto"><DialogHeader><DialogTitle>تعديل المنتج</DialogTitle><DialogDescription>تُحفظ التعديلات داخل المنصة فقط؛ حذف الصورة أو اللون أو المنتج لا يعدل الأصل في OneDrive.</DialogDescription></DialogHeader>{detail && <div className="space-y-7"><section><SectionTitle number="1" title="البيانات الأساسية" subtitle="عدل المعلومات ثم احفظها." /><div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="اسم المنتج"><Input value={draftName} onChange={event => setDraftName(event.target.value)} /></Field><Field label="السعر"><Input value={draftPrice} inputMode="decimal" onChange={event => setDraftPrice(event.target.value)} /></Field><Field label="السعر السابق" hint="اختياري؛ يجب أن يكون أعلى من السعر الحالي"><Input value={draftPreviousPrice} inputMode="decimal" placeholder="اتركه فارغًا بلا خصم" onChange={event => setDraftPreviousPrice(event.target.value)} /></Field><Field label="القياسات"><Input value={draftSizes} onChange={event => setDraftSizes(event.target.value)} placeholder="Medium، Large" /></Field><div className="sm:col-span-2"><Field label="الوصف"><Textarea value={draftDescription} onChange={event => setDraftDescription(event.target.value)} /></Field></div></div><Button className="mt-3 bg-[#183d35]" onClick={saveDetails} disabled={updateDetails.isPending}><Save className="ml-1 h-4 w-4" />حفظ البيانات</Button></section><section><SectionTitle number="2" title="الألوان والأعداد" subtitle="عدّل الاسم أو العدد ثم استخدم زر الحفظ الواحد." /><div className="mt-3 space-y-3">{colorNames.map(colorName => <div key={colorName} className="rounded-2xl border border-[#e5ded2] p-3"><div className="grid gap-2 sm:grid-cols-[1fr_1fr_auto_auto]"><Input value={renameDrafts[colorName] ?? colorName} onChange={event => setRenameDrafts(current => ({ ...current, [colorName]: event.target.value }))} /><Input inputMode="numeric" value={quantityDrafts[colorName] ?? "0"} onChange={event => setQuantityDrafts(current => ({ ...current, [colorName]: event.target.value }))} /><Button onClick={() => saveColorDetails(colorName)} disabled={!canInventory || saveColorInventory.isPending || renameColor.isPending} className="bg-[#183d35]"><Save className="ml-1 h-4 w-4" />حفظ</Button><Button variant="outline" onClick={() => removeColor(colorName)} disabled={!canDelete || deleteColor.isPending} className="border-[#e6bbb0] text-[#a14724]"><Trash2 className="ml-1 h-4 w-4" />حذف اللون</Button></div><div className="mt-3 grid grid-cols-3 gap-2 sm:grid-cols-5">{(mediaByColor[colorName] ?? []).map(item => <div key={item.mediaId} className="overflow-hidden rounded-xl border border-[#e5ded2]"><img src={item.dataUrl} alt="صورة اللون" className="aspect-square w-full object-cover" /><div className="flex gap-1 p-1"><select value={colorName} onChange={event => moveMedia(item.mediaId, event.target.value)} className="min-w-0 flex-1 rounded border bg-white px-1 text-[10px]">{colorNames.map(name => <option key={name}>{name}</option>)}</select><button type="button" onClick={() => removeMedia(item.mediaId)} className="rounded border border-[#efd5cf] px-1 text-[#a14724]" aria-label="حذف الصورة"><Trash2 className="h-3 w-3" /></button></div></div>)}</div></div>)}</div></section><section className="rounded-2xl border border-[#d8e6dd] bg-[#f7fbf8] p-4"><SectionTitle number="3" title="ربط أي صورة بلون" subtitle="تظهر هنا كل صور المنتج، حتى الصور التي تم ربطها سابقًا. أنشئ لونًا ثم اختره للصورة التي تريد نقلها." /><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_auto]"><Input value={newColorName} onChange={event => setNewColorName(event.target.value)} placeholder="اسم لون جديد، مثل: فضي" /><Button onClick={createColor} disabled={!newColorName.trim() || addColor.isPending} className="bg-[#285f4e] hover:bg-[#1c4b3d]"><Check className="ml-1 h-4 w-4" />إضافة اللون</Button></div><div className="mt-4 grid grid-cols-3 gap-2 sm:grid-cols-5">{media.map(item => <div key={item.mediaId} className="overflow-hidden rounded-xl border border-[#d9dfd9] bg-white"><img src={item.dataUrl} alt="صورة المنتج" className="aspect-square w-full object-cover" /><select value={item.colorName || ""} onChange={event => moveMedia(item.mediaId, event.target.value)} className="w-full border-t bg-white p-1.5 text-xs"><option value="" disabled>اختر لونًا</option>{colorNames.map(name => <option key={name} value={name}>{name}</option>)}</select></div>)}</div></section><section><SectionTitle number="4" title="إضافة صور" subtitle="تُحوّل المجموعة إلى WebP ثم يبدأ تحليل اللون تلقائيًا لتظهر للمراجعة." /><label className="mt-3 inline-flex cursor-pointer items-center rounded-lg border border-[#aacbbc] bg-white px-3 py-2 text-sm font-bold text-[#28604e]"><input type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={addImages} className="sr-only" disabled={uploadImage.isPending || generateAutomaticSuggestion.isPending} /><ImagePlus className="ml-1.5 h-4 w-4" />{uploadImage.isPending || generateAutomaticSuggestion.isPending ? "جارٍ رفع وتحليل الصور..." : "إضافة مجموعة صور"}</label></section><section className="rounded-2xl border border-[#efc7bd] bg-[#fff6f3] p-4"><h3 className="font-bold text-[#9c3f2d]">حذف المنتج</h3><p className="mt-1 text-xs leading-5 text-[#8d665d]">يحذف المنتج وألوانه وأعداده وصوره التشغيلية من المنصة. لا يحذف ملفات OneDrive، ولن يعاد استيراد المجلد تلقائيًا.</p><Button variant="outline" onClick={() => setProductDeleteOpen(true)} disabled={!canDelete || deleteProduct.isPending} className="mt-3 border-[#d99d8e] text-[#9c3f2d]"><Trash2 className="ml-1 h-4 w-4" />{deleteProduct.isPending ? "جارٍ حذف المنتج..." : "حذف المنتج نهائيًا"}</Button></section>{(deleteColor.error || deleteProduct.error || applyAutomaticSuggestion.error) && <p className="rounded-xl bg-[#fff0ec] p-3 text-xs text-[#9c3f2d]">{deleteColor.error?.message ?? deleteProduct.error?.message ?? applyAutomaticSuggestion.error?.message}</p>}</div>}</DialogContent></Dialog>
    <AlertDialog open={productDeleteOpen} onOpenChange={setProductDeleteOpen}><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>هل أنت متأكد من حذف المنتج؟</AlertDialogTitle><AlertDialogDescription>سيُحذف المنتج وألوانه وأعداده وصوره التشغيلية من المنصة. لن تتغير أي صورة أو ملف في OneDrive.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>لا</AlertDialogCancel><AlertDialogAction onClick={removeProduct} className="bg-[#a33f2a] hover:bg-[#87301f]">نعم، احذف المنتج</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={Boolean(colorDeleteTarget)} onOpenChange={open => !open && setColorDeleteTarget(null)}><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>هل أنت متأكد من حذف اللون؟</AlertDialogTitle><AlertDialogDescription>سيُحذف لون «{colorDeleteTarget}» مع صوره وعدده من المنصة فقط، ولن تتغير ملفات OneDrive.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>لا</AlertDialogCancel><AlertDialogAction onClick={confirmColorDelete} className="bg-[#a33f2a] hover:bg-[#87301f]">نعم، احذف اللون</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>;
}
